from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .source_api_association_config import SourceApiAssociationConfig, SourceApiAssociationConfigDict


class V1MergedApisSourceApiAssociationsRequest(SdkBaseModel):
    source_api_identifier: str = Field(alias="sourceApiIdentifier")
    """The identifier of the AppSync Source API. This is generated by the AppSync service. In most cases, source APIs
    (especially in your account) only require the API ID value or ARN of the source API. However, source APIs from other
    accounts (cross-account use cases) strictly require the full resource ARN of the source API."""

    description: Optional[str] = UNSET
    """The description field."""

    source_api_association_config: Optional[SourceApiAssociationConfig] = Field(
        default=UNSET, alias="sourceApiAssociationConfig"
    )


class V1MergedApisSourceApiAssociationsRequestDict(TypedDict):
    source_api_identifier: str
    description: NotRequired[str]
    source_api_association_config: NotRequired[SourceApiAssociationConfigDict]
